// Patch is a correction gen/main.go applies to a verse of the source data
// before bundling it (the source is a web scrape with a few defects).
type Patch struct {
	Abbrev               string
	Book, Chapter, Verse int
	Old, New             string // Old is replaced by New, once
	Reason               string
}

// Patches are the corrections applied to the bundled data.
var Patches = []Patch{
	{
		Abbrev: "ASV", Book: 40, Chapter: 18, Verse: 24,
		Old:    "ten thousand This talent was probably worth about £200, or $1000.talents.",
		New:    "ten thousand talents.",
		Reason: "the source spliced the BibleGateway footnote body into the verse text",
	},
	{
		Abbrev: "RVA", Book: 20, Chapter: 10, Verse: 1,
		Old:    "> EL hijo sabio",
		New:    "EL hijo sabio",
		Reason: "a stray \">\" before the verse in the .ewb (the start of Solomon's proverbs)",
	},
	{
		Abbrev: "RVA", Book: 66, Chapter: 22, Verse: 21,
		Old:    "vosotros. Amén. FIN.",
		New:    "vosotros. Amén.",
		Reason: "the printed edition's closing \"FIN\" (the end) is not verse text",
	},
}

// Lookup returns the manifest entry for abbrev (case-insensitive).
func Lookup(abbrev string) (Translation, bool) {
	for _, t := range Translations {
		if strings.EqualFold(t.Abbrev, abbrev) {
			return t, true
		}
	}
	return Translation{}, false
}

// Abbrevs lists the bundled abbreviations.
func Abbrevs() []string {
	out := make([]string, len(Translations))
	for i, t := range Translations {
		out[i] = t.Abbrev
	}
	return out
}

// Size returns the embedded (compressed) size of all translations in bytes.
func Size() int64 {
	var n int64
	for _, t := range Translations {
		if fi, err := fs.Stat(data, t.File); err == nil {
			n += fi.Size()
		}
	}
	return n
}

// FileSize returns a translation's embedded (compressed) size in bytes.
func FileSize(abbrev string) int64 {
	t, ok := Lookup(abbrev)
	if !ok {
		return 0
	}
	fi, err := fs.Stat(data, t.File)
	if err != nil {
		return 0
	}
	return fi.Size()
}

// Header reads a bundled translation's package header.
func Header(abbrev string) (biblepkg.Header, error) {
	t, ok := Lookup(abbrev)
	if !ok {
		return biblepkg.Header{}, fmt.Errorf("bundled bible %q: not bundled", abbrev)
	}
	f, err := data.Open(t.File)
	if err != nil {
		return biblepkg.Header{}, fmt.Errorf("bundled bible %s: %w", t.Abbrev, err)
	}
	defer f.Close()
	h, err := biblepkg.ReadHeader(f)
	if err != nil {
		return biblepkg.Header{}, fmt.Errorf("bundled bible %s: %w", t.Abbrev, err)
	}
	return h, nil
}

// Load decodes a bundled translation.
func Load(abbrev string) (bibletext.Result, error) {
	t, ok := Lookup(abbrev)
	if !ok {
		return bibletext.Result{}, fmt.Errorf("bundled bible %q: not bundled", abbrev)
	}
	f, err := data.Open(t.File)
	if err != nil {
		return bibletext.Result{}, fmt.Errorf("bundled bible %s: %w", t.Abbrev, err)
	}
	defer f.Close()
	p, err := biblepkg.Read(f)
	if err != nil {
		return bibletext.Result{}, fmt.Errorf("bundled bible %s: %w", t.Abbrev, err)
	}
	return bibletext.Result{Bible: p.Bible, Verses: p.Verses, Warnings: p.Warnings}, nil
}

// Removed lists the built-ins the operator removed (SettingRemoved).
func Removed(ctx context.Context, st *store.Store) ([]string, error) {
	if st == nil {
		return nil, errors.New("bundled bibles: nil store")
	}
	var out []string
	if _, err := st.GetSetting(ctx, SettingRemoved, &out); err != nil {
		return nil, fmt.Errorf("bundled bibles: %w", err)
	}
	return out, nil
}

// SetRemoved records (removed true) or forgets that the operator removed
// the built-in abbrev. Other abbreviations are ignored.
func SetRemoved(ctx context.Context, st *store.Store, abbrev string, removed bool) error {
	t, ok := Lookup(abbrev)
	if !ok {
		return nil
	}
	list, err := Removed(ctx, st)
	if err != nil {
		return err
	}
	list = slices.DeleteFunc(list, func(a string) bool { return strings.EqualFold(a, t.Abbrev) })
	if removed {
		list = append(list, t.Abbrev)
	}
	if list == nil {
		list = []string{}
	}
	if err := st.SetSetting(ctx, SettingRemoved, list); err != nil {
		return fmt.Errorf("bundled bibles: %w", err)
	}
	return nil
}

// Report summarises Install.
type Report struct {
	Installed []string // abbreviations added
	Skipped   []string // with reason, e.g. "KJV (already installed)"
	Version   int      // the bundle version recorded
}

// Needed reports whether Install has work to do: the library recorded no
// bundle version, or one older than Version.
func Needed(ctx context.Context, st *store.Store) (bool, error) {
	if st == nil {
		return false, errors.New("bundled bibles: nil store")
	}
	var v int
	ok, err := st.GetSetting(ctx, SettingVersion, &v)
	if err != nil {
		return false, fmt.Errorf("bundled bibles: %w", err)
	}
	return !ok || v < Version, nil
}

// Install adds the bundled translations the library lacks, matching
// abbreviations case-insensitively (a KJV imported from EasyWorship is left
// alone), and records Version. Built-ins the operator removed
// (SettingRemoved) are skipped. It is idempotent: a second run adds nothing.
// Each translation is written in one transaction, so a cancelled install
// leaves no half Bible.
func Install(ctx context.Context, st *store.Store) (Report, error) {
	rep := Report{Installed: []string{}, Skipped: []string{}}
	if st == nil {
		return rep, errors.New("install bundled bibles: nil store")
	}
	installed, err := st.ListBibles(ctx)
	if err != nil {
		return rep, fmt.Errorf("install bundled bibles: %w", err)
	}
	have := make(map[string]bool, len(installed))
	for _, b := range installed {
		have[strings.ToUpper(b.Abbrev)] = true
	}
	removed, err := Removed(ctx, st)
	if err != nil {
		return rep, fmt.Errorf("install bundled bibles: %w", err)
	}
	for _, t := range Translations {
		if err := ctx.Err(); err != nil {
			return rep, err
		}
		if slices.ContainsFunc(removed, func(a string) bool { return strings.EqualFold(a, t.Abbrev) }) {
			rep.Skipped = append(rep.Skipped, t.Abbrev+" (removed)")
			continue
		}
		if have[strings.ToUpper(t.Abbrev)] {
			rep.Skipped = append(rep.Skipped, t.Abbrev+" (already installed)")
			continue
		}
		res, err := Load(t.Abbrev)
		if err != nil {
			return rep, fmt.Errorf("install bundled bibles: %w", err)
		}
		if _, err := st.CreateBibleWithVerses(ctx, res.Bible, res.Verses); err != nil {
			if errors.Is(err, store.ErrExists) {
				rep.Skipped = append(rep.Skipped, t.Abbrev+" (already installed)")
				continue
			}
			return rep, fmt.Errorf("install bundled bible %s: %w", t.Abbrev, err)
		}
		rep.Installed = append(rep.Installed, t.Abbrev)
	}
	if err := st.SetSetting(ctx, SettingVersion, Version); err != nil {
		return rep, fmt.Errorf("install bundled bibles: %w", err)
	}
	rep.Version = Version
	return rep, nil
}
